const canvas = document.getElementById('canvas1');
const ctx = canvas.getContext("2d");

const frameWidth = 674; //largura
const frameHeight = 480; //autura
const frame = 5;

let frameCurrent = 0;
let frameControl = 0;
let frameSpeed = 6;

const sprite = new Image();
sprite.src = 'data:image/png;base64,'
sprite.onload = function(){
    animar()
}

function animar(){
    ctx.clearRect(0,0, canvas.width, canvas.height)
    const spritY = frameWidth * frameHeight;
    ctx.drawImage(
        sprite,
        0,
        spritY,
        frameWidth,
        frameHeight,
        0,
        0,
        frameWidth,
        frameHeight,
    );
    frameControl++;
    if (frameControl >= frameSpeed){
        frameControl = 0;
    }
}
